import urllib.request, re
def get(u):
    r = urllib.request.urlopen(urllib.request.Request(u, headers={"User-Agent":"Mozilla/5.0"}), timeout=30)
    return r.read().decode('utf-8', 'ignore')
for u in ["https://www.dot.ny.gov/highway-data-services",
          "https://www.dot.ny.gov/divisions/engineering/technical-services/highway-data-services"]:
    try:
        h = get(u)
        links = re.findall(r'href="([^"]+)"[^>]*>([^<]{0,120})', h)
        for href, txt in links:
            if re.search(r'vmt|vehicle.?miles|county', href+txt, re.I):
                print(u[-40:], '|', txt.strip(), '|', href)
    except Exception as e:
        print(u, "ERR", e)
EOF

