import urllib.request, json, urllib.parse
def cat(**kw):
    u="https://api.us.socrata.com/api/catalog/v1?"+urllib.parse.urlencode(kw)
    r=urllib.request.urlopen(urllib.request.Request(u, headers={"User-Agent":"Mozilla/5.0"}), timeout=40)
    return json.loads(r.read())
for q in ["VMT","vehicle miles","MOVES","traffic volume"]:
    try:
        d=cat(q=q, search_context="data.ny.gov", limit="20")
        print("==",q, d.get("resultSetSize"))
        for res in d.get("results",[])[:20]:
            print("  ", res["resource"]["name"],"|",res["resource"]["id"])
    except Exception as e: print(q,"ERR",e)
for q in ["VMT county","vehicle miles traveled county"]:
    try:
        d=cat(q=q, limit="20")
        print("== ALL:",q, d.get("resultSetSize"))
        for res in d.get("results",[])[:20]:
            print("  ", res["resource"]["name"],"|",res["resource"]["id"], res["metadata"].get("domain"))
    except Exception as e: print(q,"ERR",e)
EOF

